def extract_return_data(report):
    """
    Extract return data from sales audit report.

    Args:
        report (dict): Sales audit report.

    Returns:
        dict: Return data.
    """
    return_data = {
        "total_returns": report["returns"]["total_returns"],
        "approved_returns": report["returns"]["approved_returns"],
        "rejected_returns": report["returns"]["rejected_returns"],
        "pending_returns": report["returns"]["pending_returns"]
    }
    return return_data

